const userModel = require('../models/user.model');
const driverModel = require('../models/driver.model');
const jwt = require('jsonwebtoken');
const blackListTokenModel = require('../models/blackListToken.model');

module.exports.authUser = async (req, res, next) => {
    try {
        // Safely extract token from cookies or Authorization header
        const token = req.cookies.token || req.headers.authorization?.split(' ')[1] || null;

        if (!token) {
            return res.status(401).json({ message: 'You need to login' });
        }

        // Check if token is blacklisted
        const isBlackListed = await blackListTokenModel.findOne({ token });
        if (isBlackListed) {
            return res.status(401).json({ message: 'Token has been blacklisted. Please login again' });
        }

        // Verify JWT token
        const decoded = jwt.verify(token, process.env.JWT_SECRET);

        // Find user in the database
        const user = await userModel.findById(decoded._id);
        if (!user) {
            return res.status(401).json({ message: 'Invalid user. Please login again' });
        }

        // Attach user to request object
        req.user = user;
        next();
    } catch (error) {
        return res.status(401).json({ message: 'Invalid token. Please login again' });
    }
};

module.exports.authDriver = async (req, res, next) => {
    try {
        // Safely extract token from cookies or Authorization header
        const token = req.cookies.token || req.headers.authorization?.split(' ')[1] || null;
        if (!token) {
            return res.status(401).json({ message: 'You need to login' });
        }

        // Check if token is blacklisted
        const isBlackListed = await blackListTokenModel.findOne({ token });
        if (isBlackListed) {
            return res.status(401).json({ message: 'Token has been blacklisted. Please login again' });
        }

        // Verify JWT token
        const decoded = jwt.verify(token, process.env.JWT_SECRET);

        // Find driver in the database
        const driver = await driverModel.findById(decoded._id);
        if (!driver) {
            return res.status(401).json({ message: 'Invalid driver. Please login again' });
        }

        // Attach driver to request object
        req.driver = driver;
        next();
    } catch (error) {
        return res.status(401).json({ message: 'Invalid token. Please login again' });
    }
};

const mongoose = require('mongoose');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

const userSchema = new mongoose.Schema({
    fullname: {
        firstname: {
            type: String,
            required: true,
            minlength: [3, 'Firstname must be at least 3 characters']
        },
        lastname: {
            type: String,
            required: true,
            minlength: [3, 'Lastname must be at least 3 characters']
        }
    },
    email: {
        type: String,
        required: true,
        unique: true,
        minlength: [3, 'Email must be at least 3 characters'],
        match: [/^\S+@\S+\.\S+$/, 'Please provide a valid email address']
    },
    password: {
        type: String,
        select: false,
        required: true,
    },
    socketid: {
        type: String,
    }
});

// Generate JWT Token
userSchema.methods.generateAuthToken = function() {
    return jwt.sign({ _id: this._id }, process.env.JWT_SECRET, { expiresIn: '24h' }); // Set expiry for security
};

// Compare Password
userSchema.methods.comparePassword = async function(enteredPassword) {
    return await bcrypt.compare(enteredPassword, this.password);
};

// Hash Password Before Saving
userSchema.pre('save', async function(next) {
    if (!this.isModified('password')) return next(); // Exit early if password is not modified
    this.password = await bcrypt.hash(this.password, 12);
    next();
});

const userModel = mongoose.model('User', userSchema);

module.exports = userModel;

const mongoose = require('mongoose');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');


const driverSchema = new mongoose.Schema({
    fullname: {
        firstname: {
            type: String,
            required: true,
            minlength: [3, 'Firstname must be at least 3 characters']
        },
        lastname: {
            type: String,
            required: true,
            minlength: [3, 'Lastname must be at least 3 characters']
        }
    },
    email: {
        type: String,
        required: true,
        unique: true,
        minlength: [3, 'Email must be at least 3 characters'],
        match: [/^\S+@\S+\.\S+$/, 'Please provide a valid email address']
    },
    password: {
        type: String,
        select: false,
        required: true,
    },
    socketid: {
        type: String,
    },

    status: {
        type: String,
        enum : ['active','inactive'],
        default: 'inactive'
    },

    vehicle: {
        color: {
            type: String,
            minlength: [3, 'Color must be at least 3 characters'],
            required: true,
        },
        plateNumber: {
            type: String,
            minlength: [3, 'Plate number must be at least 3 characters'],
            required: true,
        },

        capacity: {
            type: Number,
            required: true,
            min: 1,
        },

        vehicleType: {
            type: String,
            enum : ['Car','Moto','CNG'],
            required: true,
        }
    },
    location: {
        latitude: {
            type: Number,
        },
        longitude: {
            type: Number,
        }
    }

});

// Generate JWT Token
driverSchema.methods.generateAuthToken = function() {
    return jwt.sign({ _id: this._id }, process.env.JWT_SECRET, { expiresIn: '24h' }); // Set expiry for security
};

// Compare Password
driverSchema.methods.comparePassword = async function(enteredPassword) {
    return await bcrypt.compare(enteredPassword, this.password);
};

// Hash Password Before Saving
driverSchema.pre('save', async function(next) {
    if (!this.isModified('password')) return next(); // Exit early if password is not modified
    this.password = await bcrypt.hash(this.password, 12);
    next();
});

const driverModel = mongoose.model('Driver', driverSchema);

module.exports = driverModel;

const mongoose = require('mongoose');
const jwt = require('jsonwebtoken');

const blackListTokenSchema = new mongoose.Schema({
    token: {
        type: String,
        required: true,
        unique: true
    },
    createdAt: {
        type: Date,
        default: Date.now,
        expires: 86400 // 24 hours in seconds
    }
});

const BlackListToken = mongoose.model('BlackListToken', blackListTokenSchema);

module.exports = BlackListToken;

const LocationSearchPanel = ({setopenVehiclePanel, setShow}) => {

  const locations = [
    "banani super market",
    "gulshan 2",
    "dhanmondi 27",
    "uttara sector 7",
  ]

  const handleClick = () => {
    setopenVehiclePanel(true)
    setShow(false)
  }

  return (
    <div className="px-5">
      {locations.map((location, index) => (
      <div key={index} onClick={()=>handleClick()} className='flex gap-4 border-2 p-3 border-gray-50 active:border-black rounded-xl items-center my-2 justify-start'>
        <h2 className='bg-[#eee] h-8 flex items-center justify-center w-12 rounded-full'><i className="ri-map-pin-fill"></i></h2>
        <h4 className='font-medium'>{location}</h4>
      </div>
      ))}
    </div>
  )

}

export default LocationSearchPanel

